/* Signature Icelandic Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Jonbjork": "From Jon + bjork (birch).", "Gudruneld": "From Gudrun + eld (fire).", "Sigurdurhaf": "From Sigurdur + haf (ocean).", "Annavatn": "From Anna + vatn (water/lake).", "Einarfjall": "From Einar + fjall (mountain).", "Bjorksol": "From Bjork + sol (sun).", "Jonbjorksson": "Signature patronymic-style name.", "Gudruneldsdottir": "Signature feminine patronymic-style name.", "Sigurdurhafsson": "Signature patronymic-style name.", "Einarfjallsson": "Signature patronymic-style name."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Jonbjork';
console.log(lookup(q));

